<script setup lang="ts">
import {ref} from 'vue';import PageShell from '../../components/PageShell.vue';import OrderCard from '../../components/OrderCard.vue';import EmptyState from '../../components/EmptyState.vue';import {usePage} from '../../composables/usePage';import {usePagination} from '../../composables/usePagination';import {productApi} from '../../api/product'
const filter=ref('');const pager=usePagination(p=>productApi.orders(p,filter.value));const {loading,error,load,action}=usePage(()=>pager.load(true));const tabs=[['','全部'],['PENDING_PAYMENT','待派单'],['SERVICING','服务中'],['ACCEPTED','待上门'],['COMPLETED','已完成'],['CANCELLED','已取消']];function change(s:string){filter.value=s;load()}
</script><template><PageShell title="我的订单" active="orders" :loading="loading" :error="error" @retry="load"><view class="title" style="margin-bottom:20px">每一次照顾，都有记录。</view><view class="tabs"><view v-for="t in tabs" :key="t[0]" :class="['tab',{active:filter===t[0]}]" @click="change(t[0])">{{t[1]}}</view></view><OrderCard v-for="o in pager.rows.value" :key="o.id" :order="o"/><EmptyState v-if="!loading&&!pager.rows.value.length" text="这里还没有订单，去预约一次安心照顾吧"/><button v-if="pager.rows.value.length<pager.total.value" class="outline" @click="action(()=>pager.load(),'')">加载更多</button></PageShell></template>
